      expect(typeof testServer.listen).toBe('function');
    });

    it('accepts connectionLimit in BuildServerOptions', () => {
      const testServer = buildServer({
        logger: false,
        connectionLimit: 500
      });

      expect(testServer).toBeDefined();
    });
  });

