    it('server works without explicit connectionLimit', async () => {
      const testServer = buildServer({ logger: false });

      const response = await testServer.inject({
        method: 'GET',
        url: '/health'
      });

      expect(response.statusCode).toBe(200);
      await testServer.close();
    });
  });

  describe('Health endpoint under normal conditions', () => {
    it('responds to health endpoint within limit', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      expect(response.statusCode).toBe(200);
      expect(response.json()).toEqual({ status: 'ok' });
    });

    it('returns JSON content-type on health', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      const contentType = response.headers['content-type'];
      expect(contentType).toContain('application/json');
    });
  });

  describe('Readiness endpoint under normal conditions', () => {
    it('responds to readiness endpoint', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/ready'
      });

      // Should return 503 because no config is set (not valid state)
      expect(response.statusCode).toBe(503);
    });

    it('returns JSON on readiness endpoint', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/ready'
      });

      const body = response.json();
      expect(body).toHaveProperty('status');
      expect(typeof body.status).toBe('string');
    });
  });

  describe('Connection handling behavior', () => {
    it('accepts multiple sequential requests', async () => {
      for (let i = 0; i < 10; i++) {
        const response = await server.inject({
          method: 'GET',
          url: '/health'
        });
        expect(response.statusCode).toBe(200);
      }
    });

    it('handles rapid-fire requests', async () => {
      const promises = [];
      for (let i = 0; i < 20; i++) {
        promises.push(
          server.inject({
            method: 'GET',
            url: '/health'
          })
        );
      }

      const results = await Promise.all(promises);
      results.forEach((response) => {
        expect([200, 503]).toContain(response.statusCode);
      });
    });
  });

  describe('Error handling with connectionLimit', () => {
    it('handles 503 responses gracefully', async () => {
      // Attempt many concurrent requests to potentially exceed limit
      const promises = [];
      for (let i = 0; i < 50; i++) {
        promises.push(
          server.inject({
            method: 'GET',
            url: '/health'
          }).catch((err) => ({
            statusCode: 503,
            error: err.message
          }))
        );
      }

      const results = await Promise.all(promises);

      // All requests should either succeed (200) or be rejected (which we catch as 503)
      results.forEach((response: any) => {
        expect([200, 503, undefined]).toContain(response?.statusCode);
      });
    });

    it('returns valid JSON on all successful responses', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      if (response.statusCode === 200) {
        expect(response.json()).toBeDefined();
        expect(typeof response.json()).toBe('object');
      }
    });
  });

  describe('Server stability under concurrency', () => {
    it('recovers after concurrent request spike', async () => {
      // Send spike of requests
      const promises = [];
      for (let i = 0; i < 100; i++) {
        promises.push(
          server.inject({
            method: 'GET',
            url: '/health'
          }).catch(() => null)
        );
      }
      await Promise.all(promises);

      // Server should still respond to new requests
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      expect(response.statusCode).toBe(200);
    });

    it('maintains endpoint availability', async () => {
      // Multiple sequences of requests
      for (let seq = 0; seq < 5; seq++) {
        const response = await server.inject({
          method: 'GET',
          url: '/health'
        });
        expect(response.statusCode).toBe(200);
      }
    });
  });

  describe('Request identification in responses', () => {
    it('health endpoint response is consistent', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      expect(response.statusCode).toBe(200);
      const body = response.json();
      expect(body).toHaveProperty('status');
    });

    it('response format is valid JSON', async () => {
      const response = await server.inject({
        method: 'GET',
        url: '/health'
      });

      expect(() => {
        JSON.stringify(response.json());
      }).not.toThrow();
    });
  });

  describe('Integration with buildServer options', () => {
    it('combines logger and connectionLimit options', () => {
      const testServer = buildServer({
        logger: false,
        connectionLimit: 100
      });

      expect(testServer).toBeDefined();
      expect(testServer.log).toBeDefined();
    });

    it('can be created without options', () => {
      const testServer = buildServer();
      expect(testServer).toBeDefined();
    });

    it('preserves all Fastify functionality with connectionLimit', async () => {
      const testServer = buildServer({
        logger: false,
        connectionLimit: 50
      });

      const response = await testServer.inject({
        method: 'GET',
        url: '/health'
      });

      expect(response.statusCode).toBe(200);
      expect(response.headers['content-type']).toContain('application/json');

      await testServer.close();
    });
  });
});
